def _name_for_mock(obj: Any) -> str:
    """Return a safe name for a mocked object.

    The autodoc mock objects are sometimes subscripted with non-string
    values (ex. ``TypeVar`` for generic-typed classes like ``Foo[T]``).
    ``type()`` requires the class name to be a string, and we also want
    ``__display_name__`` to always be a string.
    """
    if isinstance(obj, str):
        return obj

    for attr in ('__qualname__', '__name__'):
        value = getattr(obj, attr, None)
        if isinstance(value, str) and value:
            return value

    try:
        return str(obj)
    except Exception:
        try:
            return repr(obj)
        except Exception:
            return object.__repr__(obj)


